        <select class="form-select mb-3" id="selector" onchange="change()">
            {% for i in years reversed %}
                <option value="{{i}}" {% if i == cur_year %} selected{% endif %}>{{i}}</option>
            {% endfor %}
        </select>
    </form>




    <script>
        const yearselection = document.getElementById("yearselection");
        const selector = document.getElementById("selector");




        function change() {
            yearselection.action = selector.value;
