                            '{{rev_rec.sept}}', '{{rev_rec.oct}}', '{{rev_rec.nov}}', '{{rev_rec.dec}}']
                            .map(v => v > 0 ? v : null);



            new Chart("myChart", {
                type: "line",
                data: {
                    labels: xValues,
                    datasets: [
                        {
                            label: "Total Collection",
                            data: colData,
                            borderColor: "#28a745",
                            backgroundColor: "#28a745",
                            //borderColor: "red",
                            //backgroundColor: "red",
                            fill: false,
                            tension: 0.3
                        },
                        {
                            label: "Total Collectables",
                            data: recData,
                            borderColor: "#FF9800",
                            backgroundColor: "#FF9800",
                            //borderColor: "blue",
                            //backgroundColor: "blue",
                            fill: false,
                            tension: 0.3
                        },

                    ]
                },

            });
        </script>
    </div>
